/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: tags, asset, project
 *   Constants: importId, slotA, slotB, manifest, shared, automaticKey
 * Tests
 *   - the per-file step plans title, Disc and Track Numbers from version-2 evidence only where it has a value
 *   - evidence stored before S8, files already automated, unconfirmed files and files outside the manifest plan nothing
 *   - the album step plans the shared title, year, label and one primary entry once every file is confirmed, and only once
 *   - a value the files disagree on or one file lacks stays empty, and an album artist must be the only one on every file, with none left out
 *   - placeholder credits never become entries or labels, and a company-like album artist is written and flagged as a possible label
 *   - automation for a malformed project ID is idle without reading anything
 *   - a disc folder or file-name prefix supplies a Disc Number only when every match agrees
 *   - every automatic write is compare-and-set: empty, unchanged automatic and equal values, administrator values and the size cap
 *   - tag text is NFC and trimmed, and control, invisible formatting, over-long, over-many and malformed values are left out and flagged once
 *   - duration evidence is exact for version-2 tags and counts a stored mm:ss duration with one-second precision
 * @end-catalog */

/**
 * Tag evidence and automatic prefill without a database: the version-2 tag reader, the automation planner, the path Disc Number
 * rule, the compare-and-set matrix every automatic write goes through, the automation markers and duration evidence. All names,
 * identifiers and paths are synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import type { ImportManifest } from '../../src/administration/import/adminImportContract';
import { defaultDraftV2, derivedEntryKey, type ImportDraftOrigins, type ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { ImportAsset } from '../../src/administration/import/adminImportMediaTypes';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import { AUTOMATIC_ENTRY_SEED, discFromRelativePath, planImportAutomation, runImportAutomation } from '../../src/administration/import/adminImportAutomation';
import { importAssetDurationEvidence, readImportEmbeddedTags } from '../../src/administration/import/adminImportTags';
import { applyAdministratorChanges, applyAutomaticValues, importAutomationMarkers } from '../../src/administration/import/adminImportValueState';

const importId = '0000000000000000000000c8';
const slotA = '00000009-0000-4000-a000-0000000000c1', slotB = '00000009-0000-4000-a000-0000000000c2';
const manifest: ImportManifest = { rootLabel: 'Synthetic Folder', files: [
    { slotId: slotA, filename: '01 One.flac', relativePath: 'Synthetic Folder/CD2/01 One.flac', byteLength: 10 },
    { slotId: slotB, filename: '02 Two.flac', relativePath: 'Synthetic Folder/02 Two.flac', byteLength: null }] };
const tags = (extra: Record<string, unknown> = {}) => ({ version: 2, title: null, album: null, artists: [], albumArtists: [], label: null, year: null, discNumber: null, trackNumber: null, durationMs: null,
    identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [], ...extra });
const asset = (slotId: string, evidence: unknown, extra: Partial<ImportAsset> = {}) => ({ slotId, operationId: `00000009-0000-4000-8000-0000000000${slotId.slice(-2)}`, state: 'ready', tags: evidence, ...extra }) as ImportAsset;
const project = (assets: ImportAsset[], extra: Partial<AdminImportDocument> = {}): AdminImportDocument => ({
    _id: new ObjectId(importId), purpose: 'import', draftVersion: 2, draft: defaultDraftV2(manifest), draftOrigins: {}, manifest, media: { assets }, revision: 3, decisions: [], suggestions: [], receipts: [], ...extra
}) as unknown as AdminImportDocument;
const shared = { album: 'Synthetic Album', year: 2026, label: 'Synthetic Label', albumArtists: ['Synthetic Ensemble'] };
const automaticKey = derivedEntryKey({ importId, automatic: AUTOMATIC_ENTRY_SEED });

test('the per-file step plans title, Disc and Track Numbers from version-2 evidence only where it has a value', () => {
    const doc = project([asset(slotA, tags({ title: 'Tagged One', trackNumber: 1 })), asset(slotB, tags({ discNumber: 3, trackNumber: 2 }))]);
    (doc.draft as ImportDraftV2).tracks[1].trackNumber = 9;
    const plan = planImportAutomation(doc);
    assert.deepEqual(plan.files.map(file => file.slotId), [slotA, slotB]);
    // Each `seen` is the current value; the CD2 folder supplies slot A's disc, and slot B's disc tag is used as is.
    assert.deepEqual(plan.values, [
        { path: `tracks.${slotA}.title`, seen: '', value: 'Tagged One' }, { path: `tracks.${slotA}.discNumber`, seen: null, value: 2 }, { path: `tracks.${slotA}.trackNumber`, seen: null, value: 1 },
        { path: `tracks.${slotB}.discNumber`, seen: null, value: 3 }, { path: `tracks.${slotB}.trackNumber`, seen: 9, value: 2 }
    ]);
    // A disc tag beats the path.
    assert.deepEqual(planImportAutomation(project([asset(slotA, tags({ discNumber: 1 }))])).values, [{ path: `tracks.${slotA}.discNumber`, seen: null, value: 1 }]);
});

test('evidence stored before S8, files already automated, unconfirmed files and files outside the manifest plan nothing', () => {
    const legacy = { title: 'Legacy Title', album: 'Synthetic Album', artists: ['Synthetic Ensemble'], year: 2026, trackNumber: 1 };
    for (const [label, assets] of [
        ['version-1 evidence', [asset(slotA, legacy), asset(slotB, { ...legacy, version: 1 })]],
        ['not ready', [asset(slotA, tags({ title: 'T' }), { state: 'pending' }), asset(slotB, tags({ title: 'U' }), { state: 'unknown' })]],
        ['outside the manifest', [asset('00000009-0000-4000-a000-0000000000ff', tags({ title: 'T' })), asset(`embedded-${slotA}`, tags({ title: 'U' }))]],
        ['no evidence', [asset(slotA, null), asset(slotB, null)]],
        // A record claiming version 2 without its shape is not version-2 evidence, so it is never read as such.
        ['malformed version-2 evidence', [asset(slotA, { version: 2, title: 'T', trackNumber: 1 }), asset(slotB, { ...tags({ title: 'U', trackNumber: 2 }), identifiers: null })]]
    ] as const) assert.deepEqual(planImportAutomation(project([...assets])), { files: [], album: false, values: [] }, label);
    // Files already automated plan no per-file values, and the album step still runs once every file is confirmed (marking it done
    // even when the files share nothing).
    assert.deepEqual(planImportAutomation(project([asset(slotA, tags({ title: 'T' }), { automatedAt: new Date() }), asset(slotB, tags({ title: 'U' }), { automatedAt: new Date() })])), { files: [], album: true, values: [] });
    const automated = planImportAutomation(project([asset(slotA, tags({ title: 'T', ...shared }), { automatedAt: new Date() }), asset(slotB, tags(shared), { automatedAt: new Date() })]));
    assert.deepEqual([automated.files, automated.album, automated.values.map(value => value.path)], [[], true, ['album.title', 'album.releaseDate', 'album.label', 'album.artists']]);
    // Catalog reviews, format-1 projects and malformed drafts are never automated.
    const assets = [asset(slotA, tags({ title: 'T' })), asset(slotB, tags())];
    for (const [label, extra] of [['a catalog review', { purpose: 'catalogReview' }], ['a format-1 project', { draftVersion: null }], ['a newer format', { draftVersion: 3 }], ['a malformed draft', { draft: { album: null } }]] as const)
        assert.deepEqual(planImportAutomation(project(assets, extra as Partial<AdminImportDocument>)), { files: [], album: false, values: [] }, label);
});

test('the album step plans the shared title, year, label and one primary entry once every file is confirmed, and only once', () => {
    const plan = planImportAutomation(project([asset(slotA, tags(shared)), asset(slotB, tags(shared))]));
    assert.equal(plan.album, true);
    assert.deepEqual(plan.values, [
        { path: `tracks.${slotA}.discNumber`, seen: null, value: 2 },
        { path: 'album.title', seen: '', value: 'Synthetic Album' }, { path: 'album.releaseDate', seen: null, value: { year: 2026, month: null, day: null } },
        { path: 'album.label', seen: null, value: { name: 'Synthetic Label', musicBrainzId: null } },
        { path: 'album.artists', seen: [], value: [{ key: automaticKey, name: 'Synthetic Ensemble', role: 'primary', joinPhrase: null, musicBrainzId: null }] }
    ]);
    // Not before every manifest file is confirmed with version-2 evidence, and never after the marker.
    assert.equal(planImportAutomation(project([asset(slotA, tags(shared))])).album, false);
    assert.equal(planImportAutomation(project([asset(slotA, tags(shared)), asset(slotB, tags(shared), { state: 'pending' })])).album, false);
    assert.equal(planImportAutomation(project([asset(slotA, tags(shared)), asset(slotB, { title: null, album: 'Synthetic Album', artists: [], year: 2026, trackNumber: null })])).album, false);
    assert.equal(planImportAutomation(project([asset(slotA, tags(shared)), asset(slotB, tags(shared))], { automation: { albumAt: new Date() } })).album, false);
});

test('a value the files disagree on or one file lacks stays empty, and an album artist must be the only one on every file, with none left out', () => {
    const albumPaths = (a: Record<string, unknown>, b: Record<string, unknown>) => planImportAutomation(project([asset(slotA, tags(a)), asset(slotB, tags(b))])).values.map(value => value.path).filter(path => path.startsWith('album.'));
    assert.deepEqual(albumPaths({ ...shared, album: 'Other Album' }, shared), ['album.releaseDate', 'album.label', 'album.artists']);
    assert.deepEqual(albumPaths({ ...shared, year: 2025 }, shared), ['album.title', 'album.label', 'album.artists']);
    assert.deepEqual(albumPaths({ ...shared, label: null }, shared), ['album.title', 'album.releaseDate', 'album.artists']);
    assert.deepEqual(albumPaths({ ...shared, albumArtists: ['Synthetic Ensemble', 'Synthetic Guest'] }, { ...shared, albumArtists: ['Synthetic Ensemble', 'Synthetic Guest'] }), ['album.title', 'album.releaseDate', 'album.label']);
    assert.deepEqual(albumPaths({ ...shared, albumArtists: ['Other Ensemble'] }, shared), ['album.title', 'album.releaseDate', 'album.label']);
    // A file whose album-artist list lost a flagged name names no album artist, so the remaining name is never written as the only one.
    const partial = { ...shared, flagged: [{ field: 'albumArtists', reason: 'characters' }] };
    assert.deepEqual(albumPaths(partial, partial), ['album.title', 'album.releaseDate', 'album.label']);
    assert.deepEqual(albumPaths(partial, shared), ['album.title', 'album.releaseDate', 'album.label']);
    // A flag on another field leaves the album artist alone.
    assert.deepEqual(albumPaths({ ...shared, flagged: [{ field: 'title', reason: 'length' }] }, shared), ['album.title', 'album.releaseDate', 'album.label', 'album.artists']);
    // The track artist is never a fallback for a missing album artist.
    assert.deepEqual(albumPaths({ ...shared, albumArtists: [], artists: ['Synthetic Ensemble'] }, { ...shared, albumArtists: [], artists: ['Synthetic Ensemble'] }), ['album.title', 'album.releaseDate', 'album.label']);
});

test('placeholder credits never become entries or labels, and a company-like album artist is written and flagged as a possible label', () => {
    for (const name of ['Various Artists', 'Unknown Artist', '[unknown]', 'VA']) {
        const plan = planImportAutomation(project([asset(slotA, tags({ ...shared, albumArtists: [name] })), asset(slotB, tags({ ...shared, albumArtists: [name] }))]));
        assert.equal(plan.values.some(value => value.path === 'album.artists'), false, name);
    }
    const noLabel = planImportAutomation(project([asset(slotA, tags({ ...shared, label: '[no label]' })), asset(slotB, tags({ ...shared, label: '[no label]' }))]));
    assert.equal(noLabel.values.some(value => value.path === 'album.label'), false);
    for (const name of ['Synthetic Records', '株式会社Synthetic']) {
        const doc = project([asset(slotA, tags({ ...shared, albumArtists: [name] })), asset(slotB, tags({ ...shared, albumArtists: [name] }))]);
        const target = { draft: doc.draft as ImportDraftV2, draftOrigins: doc.draftOrigins! };
        assert.ok(applyAutomaticValues(target, planImportAutomation(doc).values).written.includes('album.artists'), name);
        assert.deepEqual(importAutomationMarkers(target.draft, target.draftOrigins), { automaticPaths: ['album.title', 'album.artists', 'album.label', 'album.releaseDate', `tracks.${slotA}.discNumber`],
            possibleLabelEntryKeys: [automaticKey], tagOnly: { artists: true, label: true } }, name);
        // Once the entries are the administrator's own, nothing rests only on file tags and nothing is flagged.
        applyAdministratorChanges(target, [{ path: 'album.artists', base: target.draft.album.artists, value: target.draft.album.artists }]);
        assert.deepEqual(importAutomationMarkers(target.draft, target.draftOrigins).possibleLabelEntryKeys, [], name);
    }
    assert.deepEqual(importAutomationMarkers(defaultDraftV2(manifest), undefined), { automaticPaths: [], possibleLabelEntryKeys: [], tagOnly: { artists: false, label: false } });
    // Automatic but empty entries and no label rest on nothing: the paths are listed, nothing is marked or flagged.
    assert.deepEqual(importAutomationMarkers(defaultDraftV2(manifest), { 'album:artists': 'automatic', 'album:label': 'automatic' }),
        { automaticPaths: ['album.artists', 'album.label'], possibleLabelEntryKeys: [], tagOnly: { artists: false, label: false } });
});

test('automation for a malformed project ID is idle without reading anything', async () => {
    assert.deepEqual(await runImportAutomation('0000000000000000000000a1', 'not-an-id'), { ran: false, written: [], skipped: [], album: false });
});

test('a disc folder or file-name prefix supplies a Disc Number only when every match agrees', () => {
    for (const [path, disc] of [['Disc 2/01.flac', 2], ['CD2/01.flac', 2], ['Album/cd 3/01.flac', 3], ['Disk 12/01.flac', 12], ['CD2-01 x.flac', 2], ['Disc_02/01.flac', 2], ['Disc 2/CD2-01 x.flac', 2], ['(CD 4)/01.flac', null]] as const)
        assert.equal(discFromRelativePath(path), disc, path);
    for (const path of ['Discography/01.flac', 'Disco 2000.mp3', 'Disc 0/01.flac', 'CD1000/01.flac', 'CD-ROM/01.flac', 'Disc 1/CD2/x.flac', '01.flac', 'Discs/01.flac'])
        assert.equal(discFromRelativePath(path), null, path);
});

test('every automatic write is compare-and-set: empty, unchanged automatic and equal values, administrator values and the size cap', () => {
    const draft = defaultDraftV2(manifest), target = { draft, draftOrigins: {} as ImportDraftOrigins };
    draft.album.title = 'Typed Album'; target.draftOrigins['album:title'] = 'administrator';
    // An empty value is written even when the administrator owns it; it becomes automatic.
    assert.deepEqual(applyAutomaticValues(target, [{ path: `tracks.${slotA}.title`, seen: '', value: 'Tagged One' }]).written, [`tracks.${slotA}.title`]);
    target.draftOrigins[`tracks:${slotB}:title`] = 'administrator';
    assert.deepEqual(applyAutomaticValues(target, [{ path: `tracks.${slotB}.title`, seen: '', value: 'Tagged Two' }]).written, [`tracks.${slotB}.title`]);
    // An automatic value automation still sees is replaced; one changed since it was seen is skipped.
    assert.deepEqual(applyAutomaticValues(target, [{ path: `tracks.${slotA}.title`, seen: 'Tagged One', value: 'Retagged One' }]).written, [`tracks.${slotA}.title`]);
    assert.deepEqual(applyAutomaticValues(target, [{ path: `tracks.${slotA}.title`, seen: 'Tagged One', value: 'Third' }]).skipped, [{ path: `tracks.${slotA}.title`, reason: 'changed' }]);
    // An administrator save over an automatic value makes it the administrator's own, which automation never overwrites.
    applyAdministratorChanges(target, [{ path: `tracks.${slotA}.title`, base: 'Retagged One', value: 'Typed One' }]);
    assert.deepEqual(applyAutomaticValues(target, [{ path: `tracks.${slotA}.title`, seen: 'Typed One', value: 'Fourth' }, { path: 'album.title', seen: 'Typed Album', value: 'Tagged Album' }]).skipped,
        [{ path: `tracks.${slotA}.title`, reason: 'administrator' }, { path: 'album.title', reason: 'administrator' }]);
    // An equal value is no write and keeps its origin.
    assert.deepEqual(applyAutomaticValues(target, [{ path: `tracks.${slotB}.title`, seen: 'Tagged Two', value: 'Tagged Two' }]).skipped, [{ path: `tracks.${slotB}.title`, reason: 'unchanged' }]);
    assert.deepEqual([draft.tracks.map(track => track.title), target.draftOrigins], [['Typed One', 'Tagged Two'],
        { 'album:title': 'administrator', [`tracks:${slotA}:title`]: 'administrator', [`tracks:${slotB}:title`]: 'automatic' }]);
    // A write that would grow the draft past 48 KB is reverted alone.
    draft.album.title = 'x'.repeat(47_900 - JSON.stringify({ ...draft, album: { ...draft.album, title: '' } }).length);
    assert.deepEqual(applyAutomaticValues(target, [{ path: `tracks.${slotB}.title`, seen: 'Tagged Two', value: 'y'.repeat(300) }]).skipped, [{ path: `tracks.${slotB}.title`, reason: 'size' }]);
    assert.equal(draft.tracks[1].title, 'Tagged Two');
});

test('tag text is NFC and trimmed, and control, invisible formatting, over-long, over-many and malformed values are left out and flagged once', () => {
    const metadata = (common: Record<string, unknown>, duration?: number) => ({ common: { track: { no: null, of: null }, disk: { no: null, of: null }, ...common }, format: { duration } }) as never;
    const clean = readImportEmbeddedTags(metadata({ title: '  Cafe\u0301  ', album: 'Synthetic Album', artist: 'Synthetic Artist', albumartist: 'Synthetic Ensemble', label: ['Synthetic Label', ' Synthetic Label'],
        year: 2026, track: { no: 4, of: 9 }, disk: { no: 2, of: 3 }, barcode: '400-6381 333931', catalognumber: ['SYN-001'], isrc: ['us-abc-26-00001'], musicbrainz_albumid: '00000009-0000-4000-8000-0000000000F2' }, 251.4004));
    assert.deepEqual(clean, { version: 2, title: 'Caf\u00e9', album: 'Synthetic Album', artists: ['Synthetic Artist'], albumArtists: ['Synthetic Ensemble'], label: 'Synthetic Label', year: 2026, discNumber: 2, trackNumber: 4,
        durationMs: 251_400, identifiers: { barcode: '4006381333931', catalogNumber: 'SYN-001', isrc: 'USABC2600001', musicBrainzReleaseId: '00000009-0000-4000-8000-0000000000f2' }, flagged: [] });
    const dirty = readImportEmbeddedTags(metadata({ title: 'Bell\u0007', album: 'Zero\u200bWidth', artists: ['Ok', 'Bad\u0000', 'n'.repeat(201), 'Ok', 'Also\u200d'], albumartists: ['m'.repeat(5_000)],
        label: ['l'.repeat(201)], catalognumber: ['c'.repeat(101)], barcode: '4006381333932', isrc: ['NOPE'], musicbrainz_albumid: 'not-an-id', year: 0, track: { no: 10_000 }, disk: { no: 1_000 } }, 86_401));
    assert.deepEqual([dirty.title, dirty.album, dirty.artists, dirty.albumArtists, dirty.label, dirty.identifiers, dirty.year, dirty.trackNumber, dirty.discNumber, dirty.durationMs],
        [null, null, ['Ok'], [], null, { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, null, null, null, null]);
    assert.deepEqual(dirty.flagged, [{ field: 'barcode', reason: 'format' }, { field: 'catalogNumber', reason: 'length' }, { field: 'isrc', reason: 'format' }, { field: 'musicBrainzReleaseId', reason: 'format' },
        { field: 'title', reason: 'characters' }, { field: 'album', reason: 'characters' }, { field: 'artists', reason: 'characters' }, { field: 'artists', reason: 'length' }, { field: 'albumArtists', reason: 'length' }, { field: 'label', reason: 'length' }]);
    // More than ten distinct names are over the limit and left out whole, never cut to the first ten (ten, each repeated, are
    // kept); a whitespace-only value is empty, not flagged; non-text values never throw.
    const many = readImportEmbeddedTags(metadata({ artists: Array.from({ length: 11 }, (_, index) => `Artist ${index}`), albumartists: Array.from({ length: 20 }, (_, index) => `Ensemble ${index % 10}`),
        title: '   ', album: 7, label: [3, ' Plain Label '] }));
    assert.deepEqual([many.artists, many.albumArtists.length, many.title, many.album, many.label, many.flagged], [[], 10, null, null, 'Plain Label', [{ field: 'artists', reason: 'length' }]]);
    // A label, catalogue number or ISRC with several distinct values is left out and flagged, never cut to its first value.
    const several = readImportEmbeddedTags(metadata({ label: ['First Label', 'Second Label'], catalognumber: ['SYN-001', 'SYN-002'], isrc: ['USABC2600001', 'USABC2600002'] }));
    assert.deepEqual([several.label, several.identifiers.catalogNumber, several.identifiers.isrc, several.flagged],
        [null, null, null, [{ field: 'catalogNumber', reason: 'format' }, { field: 'isrc', reason: 'format' }, { field: 'label', reason: 'format' }]]);
    assert.equal(readImportEmbeddedTags({} as never).title, null);
});

test('duration evidence is exact for version-2 tags and counts a stored mm:ss duration with one-second precision', () => {
    assert.deepEqual(importAssetDurationEvidence({ tags: tags({ durationMs: 251_400 }) as never, duration: '04:11' }), { durationMs: 251_400, durationPrecisionMs: 0 });
    assert.deepEqual(importAssetDurationEvidence({ tags: { title: null, album: null, artists: [], year: null, trackNumber: null }, duration: '04:11' }), { durationMs: 251_000, durationPrecisionMs: 1000 });
    assert.deepEqual(importAssetDurationEvidence({ tags: tags() as never, duration: '1:02:03' }), { durationMs: 3_723_000, durationPrecisionMs: 1000 });
    for (const duration of [null, '', 'four minutes', '00:00']) assert.equal(importAssetDurationEvidence({ tags: null, duration }), null, String(duration));
});
